from pathlib import Path
import json,hashlib,sys,subprocess
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
B=Path(__file__).resolve().parents[1];P=B/'processed'
def load(n):return json.loads((P/n).read_text())
def save(n,v):(P/n).write_text(json.dumps(v,ensure_ascii=False,indent=2,allow_nan=False))
methods=[
{'method':'RCT','role':'future causal effects','applicable_now':False,'requires':['random assignment at appropriate cluster level','outcome and follow-up measurements','noncompliance and spillover data'],'reason':'an evaluation design, not a unit conversion for existing incompatible ratings','source':'https://www.povertyactionlab.org/resource/introduction-randomized-evaluations'},
{'method':'Difference-in-differences','role':'future causal effects','applicable_now':False,'requires':['treated and valid comparison groups','pre/post common outcomes','treatment timing','defensible parallel trends and no anticipation'],'reason':'current evaluation snapshots and reporting periods are not an untreated outcome panel','source':'https://arxiv.org/abs/1803.09015'},
{'method':'Effect-size meta-analysis','role':'pool comparable causal effects','applicable_now':False,'requires':['same outcome construct','effect estimate and standard error','evaluation design and comparison','treatment context'],'reason':'standardized effect size does not make all domains interchangeable','source':'https://www.cochrane.org/authors/handbooks-and-manuals/handbook/current/chapter-10'},
{'method':'Ordinal multi-facet IRT across agencies','role':'potential source scale calibration','applicable_now':False,'requires':['shared anchor projects or items','connected agency-item graph','measurement invariance and source/rater metadata'],'reason':'agency severity and donor differences cannot be distinguished from existing non-overlapping ratings; priors alone impose identification','source':'https://arxiv.org/abs/2108.08604'},
{'method':'Hierarchical logistic-normal beta-binomial','role':'planning/results/data process alignment estimation','applicable_now':'provisional narrow construct','implemented':True,'source':'https://www.itl.nist.gov/div898/software/dataplot/refman2/auxillar/bbnpdf.htm'},
{'method':'Within-agency hierarchical Rasch-style common-item output attainment','role':'common reference output-target measurement','applicable_now':'numerical pilot only; rejected for public ranking','implemented':True,'source':'https://mc-stan.org/docs/stan-users-guide/regression.html'}]
save('method_comparison.json',methods)
save('formula_specification.json',{'version':'0.4-methods-research','subjectivity_policy':{'investigator_score_assignment':False,'institutional_ordinal_ratings_in_fitted_models':False,'raw_self_reports_still_subject_to_bias':True,'indicator_selection_weights_model_assumptions_are_design_choices':True},'process_model':{'scope':'all-sector GPEDC largest-intervention sample; no sector imputation','components':['ownership','results_alignment','government_data'],'observations':{'ownership':'k=1/0 explicitly reported objective source, n=1; conflicts/empty remain missing','results_alignment':'k=B2Q10x1,n=B2Q10','government_data':'k=B2Q10x2,n=B2Q10'},'theta_prior':'theta[g,j] ~ Normal(m[j], tau[j]^2)','latent_project_share':'q[p,j] ~ Beta(kappa[j]*sigmoid(theta[g,j]), kappa[j]*(1-sigmoid(theta[g,j])))','observation':'K[p,j] ~ Binomial(N[p,j],q[p,j]); ownership reduces to Bernoulli','hyper_estimation':'maximum marginal likelihood, normal Gauss-Hermite quadrature; no manually scored input','score':'C_process[g] = (100/3) * sum_j E[sigmoid(theta[g,j]) | observations and fitted hyperparameters]','unobserved_components':'no total; prior-only estimates never promoted to observed scores','interval':'Bonferroni union bound of marginal posterior intervals conditional on fitted hyperparameters','weights':'1/3 inherited GPEDC three-component balance; not objectively optimal or learned social values','not_measured':['goal achievement','sustainability','causal interaction','future success']},'output_model':{'eligibility':'closed single-recipient activities, past observation period, one numeric target and actual, target>0, forecast labels excluded','binary_measure':'Y[p,j] = 1(actual[p,j] >= target[p,j]); target>=actual is not defined as a causal benefit','linear_predictor':'logit Pr(Y[p,j]=1) = beta0 + u[recipient,sector] + v[indicator,unit] + a[project]','priors':'u,v ~ Normal(0,1/lambda); a ~ Normal(0,1/lambda_project)','common_items':'exact source indicator title and unit shared by >=2 recipient countries within a sector; connected graph required','standardization':'C_output[g] = (100/J) * sum_j E_posterior E_a [sigmoid(beta0+u[g]+v[j]+a)] over fixed sector-specific common basket','estimation':'penalized likelihood with project-level nested holdout penalty selection; Laplace approximation for conditional uncertainty','validation_gate':'all three pilot sectors failed to beat pooled baseline in nested holdout; not recommended for public rank','remaining_bias':['endogenous target ambition','missing baselines','selected closed projects','unverified independent project identities','source reporting errors','different case mix'],'cross_agency_equivalence':False},'legacy_four_pillar_formula':{'weights':[.30,.30,.25,.15],'status':'not used by automatic prototypes; has no common objective inputs for all four dimensions'},'country_grade_combination':'display separately; GPEDC inputs overlap with country grades, so do not add as independent evidence','universal_chemistry_score':None})
save('required_data_schema.json',{'automatic_process_minimum':['provider_country','provider_agency_id','recipient_iso3','stable_project_id','DAC_sector_code','reporting_period','objective_source_flags','total_results_indicators','country_framework_indicator_count','government_data_indicator_count','source_url','sample_selection_rule'],'objective_outputs_minimum':['indicator_definition_id','unit','direction','baseline_value_and_date','original_target_and_date','revised_target_and_revision_reason','actual_value_and_date','project_closed_date','cofinancing_roles','subproject_parent_id','verification_method'],'cross_agency_linking':['common_anchor_project_or_indicator_id','definition_equivalence_evidence','source_scale_or_measurement_rule','connected_linking_graph'],'causal_extension':['treatment_assignment_or_timing','comparable_pre_and_post_outcome_panel','control_group_definition','clustering_and_spillovers','effect_estimate_and_standard_error']})
# Scientific plot from saved numerical outputs; no ranking based on unsupported score differences.
cv=load('process_cross_validation.json');fig,axs=plt.subplots(1,2,figsize=(12,4.8),layout='constrained');labels=['Planning alignment','Results indicators','Government data'];keys=['ownership','results_alignment','government_data'];x=np.arange(3);width=.24
for off,(model,label,col) in enumerate([('pooled_project_mean','Pooled baseline','#999999'),('pair_smoothed_project_mean','Smoothed pair mean','#d38b36'),('hierarchical_bb','Hierarchical model','#2569a7')]):
 vals=[next(r['mean_squared_error'] for r in cv if r['component']==k and r['model']==model) for k in keys];axs[0].bar(x+(off-1)*width,vals,width,label=label,color=col)
axs[0].set_xticks(x,labels,rotation=12);axs[0].set_ylabel('Held-out mean squared error (lower is better)');axs[0].set_title('Process model: whole-project holdout');axs[0].legend(fontsize=8);axs[0].spines[['top','right']].set_visible(False)
rows=sorted([r for r in load('target_standardized_scores.json') if r['sector']=='health'],key=lambda r:r['recipient']);ys=np.arange(len(rows));vals=np.array([r['target_attainment_common_basket_score'] for r in rows]);ints=np.array([r['conditional_laplace_95'] for r in rows]);axs[1].errorbar(vals,ys,xerr=np.array([vals-ints[:,0],ints[:,1]-vals]),fmt='o',color='#2569a7',capsize=3);axs[1].set_yticks(ys,[r['recipient'] for r in rows]);axs[1].set_xlim(0,100);axs[1].set_xlabel('AFD output target-attainment score (research pilot)');axs[1].set_title('Health pilot: wide conditional intervals');axs[1].spines[['top','right']].set_visible(False);fig.suptitle('Measurement pilots: diagnostics determine what can be adopted',fontsize=13);fig.savefig(B/'figures/model_validation.png',dpi=180);plt.close(fig)
# Summary and raw acquisition integrity; PDFs remain research originals, not an automatic public redistribution package.
save('analysis_summary.json',{'process':load('process_model_summary.json'),'data':load('data_inventory.json'),'target_model_adoption':load('model_adoption_decisions.json')['outcome'],'methodology_derived':True,'scores_are_research_prototypes':True,'new_investigator_ratings':0,'geographic_dummy_fields_not_used_as_sectors':True})
inv=[]
for f in sorted(B.rglob('*')):
 if f.is_file() and '.venv' not in f.parts and '__pycache__' not in f.parts and f.name!='file_inventory.json':inv.append({'path':str(f.relative_to(B)),'bytes':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()})
save('file_inventory.json',inv)
print('summary and figure ready')
